function detailQuickFacts(p){return `<dl class="detail-facts">${Object.entries(p.spec).slice(0,4).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`}
function detailBuyingGuide(p){
 const guides={record:['안쪽 페이지부터 골라보세요','표지 다음은 내가 쓰는 방식이에요. 일정 기록용인지, 자유롭게 쓰는 노트인지 내지와 규격을 함께 확인하세요.',['크기','매수','내지','종이','페이지','구성']],write:['작은 칸에도 편하게 쓰려면','심 굵기와 잉크 종류를 먼저 확인하세요. 바디 색과 실제 잉크 색은 다를 수 있어요.',['심굵기','잉크','방식','구성','색상']],deco:['붙이기 전에, 구성부터','스티커·메모는 한 장 크기와 총 매수를, 테이프는 폭과 길이를 확인하세요. 도장과 도구는 별도 준비물이 있는지 살펴보세요.',['크기','구성','매수','소재','잉크패드','길이']],custom:['내 사진이 작은 스티커가 되기까지','선명한 사진을 고르고 구성과 완성 크기를 확인하세요. 사진 선택은 브라우저 미리보기용이며, 데모 주문에서는 제작 파일이 전송되지 않아요.',['구성','크기','소재','제작','사진']],hobby:['완성할 때까지 즐거운 준비','만들기 키트는 구성품과 별도 준비물을, 슬라임·말랑이는 보관 방법과 사용 주의사항을 확인하세요.',['구성','용량','크기','소재','준비물','사용연령']],gift:['박스를 열기 전에 확인할 것','다이어리 종류와 원하는 색감을 고르면 같은 품목군 안에서 랜덤으로 구성돼요. 사진 속 모든 상품을 담은 고정 세트는 아니에요.',['구성','가치보장','필수품목','깜짝소품']],pouch:['담을 문구와 크기를 맞춰보세요','가지고 다니는 펜 길이와 파우치 규격을 비교하세요. 소재와 세탁 안내도 함께 확인해주세요.',['크기','소재','구성','세탁']]};
 const [title,copy,keys]=guides[p.category]||guides.deco;
 const facts=Object.entries(p.spec).filter(([key])=>keys.includes(key));
 return `<section class="detail-buying-guide" id="detail-specs"><span class="eyebrow">SIZE & CONTENTS</span><h3>${title}</h3><p>${copy}</p><div class="buying-facts">${facts.map(([key,value])=>`<article><span>${esc(key)}</span><strong>${esc(value)}</strong></article>`).join('')}</div><p class="detail-example-note">상품 사진과 사양은 쇼핑몰 포트폴리오용 예시입니다. 활용 사진 속 주변 소품은 기본 구성에 포함되지 않습니다.</p></section>`;
}
function detailFAQs(p,extra){return `<section class="detail-faq" id="detail-delivery"><span class="eyebrow">BEFORE YOU DECIDE</span><h3>구매 전에 궁금한 것</h3><details open><summary>무엇이 포함되나요?</summary><p>${esc(p.spec.구성||p.description)}. 옵션에 따라 구성과 디자인이 달라질 수 있으니 선택한 옵션을 확인해주세요.</p></details><details><summary>사용할 때 주의할 점이 있나요?</summary><p>${esc(extra.notice)}</p></details><details><summary>배송비와 출고 안내는 어떻게 되나요?</summary><p>상품 합계 30,000원 이상은 무료배송, 그 미만은 3,000원입니다. ${p.customizable?'주문제작 예시는 시안 확정 후 영업일 기준 5–7일 출고로 설정되어 있습니다.':'일반 상품 예시는 평일 오전 11시 이전 주문 시 당일 출고로 설정되어 있습니다.'} 현재 주문·결제는 데모이며 실제 배송이 진행되지 않습니다.</p></details><details><summary>교환·반품은 어떻게 하나요?</summary><p>${p.customizable?'주문제작은 시안 확정 후 단순 변심 교환·반품이 제한됩니다.':'미사용 상품은 수령 후 7일 이내 접수하는 기준입니다.'} 불량·오배송은 고객센터 확인 후 처리하는 예시입니다.</p></details></section>`}
function shippingProgress(){const subtotal=cartSummary().subtotal;return subtotal>=30000?'장바구니 상품 금액이 무료배송 기준을 채웠어요.':`무료배송까지 ${won(30000-subtotal)} 남았어요.`}
document.addEventListener('click',event=>{
 const tab=event.target.closest('[data-detail-section]');if(tab){document.getElementById(tab.dataset.detailSection)?.scrollIntoView({behavior:'smooth'});return}
 const quantity=event.target.closest('[data-detail-quantity]');if(quantity){const input=document.getElementById('detail-quantity');input.value=Math.min(99,Math.max(1,Number(input.value||1)+Number(quantity.dataset.detailQuantity)));refreshDetailTotal();return}
 const buy=event.target.closest('[data-buy-now]');if(buy){const info=buy.closest('.detail-info');add(buy.dataset.buyNow,Number(document.getElementById('detail-quantity')?.value||1),info.querySelector('#product-option')?.value);startCheckout()}
});
function refreshDetailTotal(){const input=document.getElementById('detail-quantity');if(!input)return;input.value=Math.min(99,Math.max(1,Math.floor(Number(input.value)||1)));const p=byId(location.hash.split('/')[1]);if(p)document.querySelector('.detail-total strong').textContent=won(p.price*Number(input.value))}
document.addEventListener('change',event=>{if(event.target.id==='detail-quantity')refreshDetailTotal()});
